"use client";
/* Boing, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Boing(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("boing"); }, []);
  return React.createElement("piix-pal", { "pal": "boing", ...piixAttrs(props) });
}

export default Boing;
